mapper.update:
UPDATE products
   SET status = #{status}
 WHERE id = #{id}

UPDATE products
   SET stock_quantity = stock_quantity - #{quantity}
 WHERE id = #{id}
   AND status = 'ACTIVE'
   AND stock_quantity IS NOT NULL
   AND stock_quantity >= #{quantity}

UPDATE products
   SET review_count = #{reviewCount},
       average_rating = #{averageRating}
 WHERE id = #{id}

UPDATE products
   SET stock_quantity = stock_quantity + #{quantity}
 WHERE id = #{id}
   AND stock_quantity IS NOT NULL

